<script setup>
import { computed, ref } from 'vue';
import { Link, useForm, router } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
const props=defineProps({series:Object,coverUrl:String,nextSortOrder:{type:Number,default:1},readingLevels:{type:Array,default:()=>[]}});
const editing=computed(()=>!!props.series);
const form=useForm({title:props.series?.title||'',translation:props.series?.translation||'',author:props.series?.author||'',level:props.series?.level||'',sortOrder:props.series?.sort_order??props.nextSortOrder,description:props.series?.description||'',rightsType:props.series?.rights_type||'',rightsNote:props.series?.rights_note||'',coverImage:null});
const coverPreview=ref(props.coverUrl||'');
function onCoverChange(file){if(!file.raw)return;coverPreview.value=URL.createObjectURL(file.raw);form.coverImage=file.raw}
function save(){form.transform(data=>({...data})).submit(editing.value?'put':'post',editing.value?`/admin/series/${props.series.id}`:'/admin/series',{forceFormData:true})}
function chapterAction(chapter,action){if(action==='edit'){router.visit(`/admin/series/${props.series.id}/chapters/${chapter.id}/edit`);return}if(action==='up'||action==='down'){router.post(`/admin/series/${props.series.id}/chapters/${chapter.id}/move/${action}`);return}router.post(`/admin/series/${props.series.id}/chapters/${chapter.id}/${action}`)}
</script>
<template><AdminLayout :title="editing?'编辑外刊小说':'新建外刊小说'" section="内容管理 / 外刊小说" :description="editing?`小说 ID #${series.id} · 管理作品信息和章节目录`:'先创建小说信息，保存后即可添加章节。'"><template #actions><Link class="btn secondary" href="/admin/series">← 返回列表</Link></template>
  <div class="series-editor"><section class="card"><div class="card-header"><div><h2>小说信息</h2><p>作品名称、封面、简介和版权来源</p></div></div><div class="card-body"><form class="form-stack" @submit.prevent="save"><div class="form-grid"><div class="form-field"><label>英文标题 <b class="required-mark">*</b></label><el-input v-model="form.title" required/></div><div class="form-field"><label>中文标题</label><el-input v-model="form.translation"/></div><div class="form-field"><label>作者</label><el-input v-model="form.author"/></div><div class="form-field"><label>阅读级别</label><el-select v-model="form.level" clearable placeholder="请选择阅读级别"><el-option v-for="level in readingLevels" :key="level.value" :value="level.value" :label="level.label" :disabled="level.disabled"/></el-select></div><div class="form-field wide"><label>小说简介</label><el-input v-model="form.description" type="textarea" :rows="4"/></div><div class="form-field wide"><label>方形封面</label><div class="cover-upload"><div class="cover-preview square"><img v-if="coverPreview" :src="coverPreview" alt="封面预览"><span v-else>暂无封面</span></div><div class="cover-upload-controls"><el-upload :auto-upload="false" :show-file-list="false" accept="image/jpeg,image/png,image/webp" :on-change="onCoverChange"><el-button>选择封面</el-button></el-upload><p class="form-hint">建议 1:1 方图，最大 4 MB。</p></div></div></div></div><div class="form-grid"><div class="form-field"><label>版权来源类型 <b class="required-mark">*</b></label><el-select v-model="form.rightsType" placeholder="请选择"><el-option value="original" label="原创"/><el-option value="authorized" label="已获授权"/><el-option value="public_domain" label="公版作品"/><el-option value="excerpt" label="摘编 / 节选"/><el-option value="other" label="其他"/></el-select></div><div class="form-field wide"><label>版权与来源说明</label><el-input v-model="form.rightsNote" type="textarea" :rows="3" placeholder="注明授权方、来源链接、授权范围或公版依据"/></div></div><div class="section-actions"><el-button type="primary" native-type="submit" :loading="form.processing">{{editing?'保存小说信息':'创建小说'}}</el-button><span class="helper">小说级版权来源类型可作为章节发布依据。</span></div></form></div></section>
  <section v-if="editing" class="card"><div class="card-header"><div><h2>章节目录</h2><p>上下移动可调整前台目录顺序；章节阅读页复用精读详情布局。</p></div><Link :href="`/admin/series/${series.id}/chapters/create`"><el-button type="primary" plain>＋ 添加章节</el-button></Link></div><div class="card-body chapter-list"><div v-if="!series.chapters?.length" class="empty-state compact"><strong>暂时没有章节</strong><span>添加第一章后即可继续编辑正文和学习内容。</span></div><div v-for="(chapter,index) in series.chapters" :key="chapter.id" class="chapter-row"><span class="chapter-number">{{String(chapter.chapter_no).padStart(2,'0')}}</span><div class="chapter-info"><strong>{{chapter.translation||chapter.title}}</strong><small>{{chapter.title}}</small></div><el-tag :type="chapter.status==='published'?'success':'info'" size="small">{{chapter.status==='published'?'已上架':'草稿'}}</el-tag><div class="chapter-actions"><el-button link :disabled="index===0" @click="chapterAction(chapter,'up')">上移</el-button><el-button link :disabled="index===series.chapters.length-1" @click="chapterAction(chapter,'down')">下移</el-button><el-button link type="primary" @click="chapterAction(chapter,'edit')">编辑</el-button><el-button link :type="chapter.status==='published'?'danger':'success'" @click="chapterAction(chapter,chapter.status==='published'?'unpublish':'publish')">{{chapter.status==='published'?'下架':'发布'}}</el-button></div></div></div></section>
  <el-alert v-if="editing&&series.status!=='published'" title="小说当前为草稿；发布小说前需选择版权来源类型，并至少有一个已发布章节。来源说明可不填写。" type="info" :closable="false" show-icon/>
  </div>
</AdminLayout></template>
<style scoped>
.series-editor{display:grid;gap:20px}.chapter-list{display:grid;gap:10px}.chapter-row{display:flex;align-items:center;gap:14px;padding:14px;border:1px solid #ebeef5;border-radius:12px;background:#fff}.chapter-number{font-size:18px;font-weight:700;color:#8b4d35;min-width:36px}.chapter-info{flex:1;min-width:0}.chapter-info strong,.chapter-info small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.chapter-info small{margin-top:4px;color:#909399}.chapter-actions{display:flex;align-items:center}.empty-state.compact{padding:22px}
@media(max-width:760px){.chapter-row{flex-wrap:wrap}.chapter-info{min-width:calc(100% - 60px)}.chapter-actions{width:100%;justify-content:flex-end}}
</style>
